const i={ui:{fig:"Fig. 2",title:"Zipper with end tabs",svgLabel:"An isometric drawing of how the ends of a zipper are closed with fabric tabs: a strip a little wider than the zipper tape folded like bias tape, two edges to the middle and then in half; slipped over each end of the zipper and stitched along its folded edges, just past the stop, never over it.",prev:"Previous step",dot:(e,t)=>e?`Step ${e}: ${t}`:t,start:"Steps →",next:"Next →",overview:"Overview",stepOf:(e,t)=>`Step ${e} of ${t}`,machine:e=>`Machine: ${e.toLowerCase()}`,inThisStep:"In this step",takeApart:"Lift the tabs",putTogether:"Put the tabs back",replay:"↻ Replay",parts:"Parts",allSteps:"Step-by-step instructions",endView:"END VIEW"},stitches:{straight:"Straight stitch"},labels:{strip:"a strip of fabric",widerThanTape:"a little wider than the tape",edgesMiddle:"edges to the middle",press:"press",inHalf:"fold in half",slipOn:"over the end of the zipper",pastStop:"just past the stop",alongEdge:"along the folded edges",notOverStop:"not over the stop",otherEnd:"the other end, the same way",thenLined:"then: as in the first way"},steps:[{title:"Zipper with end tabs",text:"Both ends of the zipper are closed with small fabric tabs, stitched just past the stops. Tap to lift the tabs."},{title:"A strip of fabric",text:"Cut a strip of fabric a little wider than the zipper tape, one for each end of the zipper.",details:["Cut a short strip of fabric a little wider than the zipper tape: the tab covers the end of the zipper from edge to edge.","You need two: one for each end of the zipper.","Patterns give different sizes for the tab; what matters is that it is a little wider than the zipper tape."]},{title:"Edges to the middle",text:"Lay the strip wrong side up, fold two opposite edges to the middle and press, like bias tape.",details:["Lay the strip wrong side up.","Fold two opposite edges in so they meet in the middle, wrong sides together.","Press the folds with the iron."]},{title:"Fold in half",text:"Fold the strip in half along the middle, the folded edges inside, and press. The tab is ready: a fold on one side, the folded edges on the other.",details:["Fold the strip in half along the middle, so the folded edges meet inside.","Press: the tab now has a fold on one side and the two folded edges on the other.","Make the second tab the same way."]},{title:"Over the end",text:"Slip the tab over the end of the zipper: the end goes inside, up to the fold, and the folded edges come just past the stop.",details:["Open the tab a little and slip the end of the zipper inside, right up to the fold.","The folded edges come just past the stop, not over it.","The tab sticks out a little on both sides of the zipper."]},{title:"Stitch the tab",text:"With the zipper foot, stitch along the folded edges of the tab, through the tab and the zipper tape. Never sew over the stop or the teeth.",details:["Put on the zipper foot: it lets you stitch close to the folded edges.","Stitch across the tab, close to its folded edges, through all its layers and the zipper tape.","Keep the stitching on the tape, past the stop: never sew over the stop or the teeth. They are often metal, and the needle can break."]},{title:"The other end",text:"Slip the second tab over the other end and stitch it the same way, with the zipper foot, past the stop there. Then the zipper is sewn in like the lined zipper pouch.",details:["Slip the second tab over the other end of the zipper, the folded edges just past the stop.","With the zipper foot, stitch along the folded edges, not over the stop.","The rest is sewn as in the first way, the lined zipper pouch: the link is under this figure."]}],legend:[{title:"Tab",text:"a strip of fabric folded like bias tape · a little wider than the zipper tape"},{title:"Stitching",text:"along the folded edges of the tab, past the stop"},{title:"Stop",text:"never sewn over"},{title:"Zipper",text:"its ends inside the tabs"}]};export{i as default};
